import {validComponents} from './scene-components.js';
import {Quaternion} from 'three';
const finite=v=>Number.isFinite(v)&&Math.abs(v)<=1e6;
const vector=(v,n)=>Array.isArray(v)&&v.length===n&&v.every(finite);
export function validRecordedState(type,track,value){
  if(type==='componentState')return typeof track.component==='string'&&track.component.length>0&&(value===null||value?.id===track.component&&value.type!=='Transform'&&validComponents([value]))&&JSON.stringify(value).length<=65536;
  return type==='skeletalPose'&&Array.isArray(value)&&value.length<=2048&&new Set(value.map(b=>b?.bone)).size===value.length&&value.every(b=>typeof b?.bone==='string'&&b.bone.length>0&&b.bone.length<=160&&vector(b.position,3)&&vector(b.scale,3)&&b.scale.every(v=>v>0)&&vector(b.quaternion,4)&&Math.abs(Math.hypot(...b.quaternion)-1)<.001);
}
export function captureSkeletalPose(group){const rows=[],names=new Set();group?.traverse(b=>{if(!b.isBone)return;if(!b.name||names.has(b.name))throw Error('골격 녹화에는 고유한 뼈 이름이 필요해요.');names.add(b.name);rows.push({bone:b.name,position:b.position.toArray(),quaternion:b.quaternion.toArray(),scale:b.scale.toArray()});});return rows;}
export function applySkeletalPose(group,pose){if(!validRecordedState('skeletalPose',{},pose))throw Error('녹화 골격 포즈 형식 오류');const bones=new Map();group?.traverse(b=>{if(b.isBone){if(bones.has(b.name))throw Error('중복 뼈 이름은 재생할 수 없어요.');bones.set(b.name,b);}});if(pose.some(p=>!bones.has(p.bone)))throw Error('녹화한 뼈가 대상에 없어요.');for(const p of pose){const bone=bones.get(p.bone);bone.position.fromArray(p.position);bone.quaternion.fromArray(p.quaternion).normalize();bone.scale.fromArray(p.scale);}group?.updateMatrixWorld(true);}
export function applyComponentStates(object,changes){const next=[...(object.components||[])];for(const {track,value} of changes){if(!validRecordedState('componentState',track,value))throw Error('녹화 컴포넌트 형식 오류');if(value===null){const i=next.findIndex(c=>c.id===track.component);if(i>=0)next.splice(i,1);}}for(const {track,value,index} of changes){if(value===null)continue;const i=next.findIndex(c=>c.id===track.component);if(i<0)next.splice(index===undefined?next.length:Math.min(index,next.length),0,structuredClone(value));else next[i]=structuredClone(value);}if(!validComponents(next))throw Error('녹화 컴포넌트 조합을 확인하세요.');object.components=next;}
export function applyComponentState(object,track,value){applyComponentStates(object,[{track,value}]);}

const samePoseLayout=(a,b)=>a.length===b.length&&a.every((bone,i)=>bone.bone===b[i].bone);
export class SkeletalPoseTrack{
  constructor(group,keys,{time}={}){this.group=group;this.keys=[...keys].sort((a,b)=>a.time-b.time);if(!this.keys.length||this.keys.some(k=>!Number.isFinite(k.time)||!validRecordedState('skeletalPose',{},k.value)))throw Error('골격 트랙 포즈를 확인하세요.');this.layouts=this.keys.map(k=>JSON.stringify(k.value.map(b=>b.bone)));this.q=new Quaternion();this.bind(Math.max(0,this.keys.findLastIndex(k=>k.time<=(time??this.keys[0].time))));}
  bind(index){const signature=this.layouts[index];if(signature===this.signature)return;const bones=new Map();this.group?.traverse(b=>{if(b.isBone){if(bones.has(b.name))throw Error('중복 뼈 이름은 재생할 수 없어요.');bones.set(b.name,b);}});const names=this.keys[index].value.map(b=>b.bone);this.bones=names.map(name=>{const bone=bones.get(name);if(!bone)throw Error('녹화 뼈가 대상에 없어요: '+name);return bone;});this.signature=signature;}
  sample(time){if(!Number.isFinite(time))throw Error('골격 시간 값을 확인하세요.');let lo=0,hi=this.keys.length;while(lo<hi){const m=(lo+hi)>>1;if(this.keys[m].time<=time)lo=m+1;else hi=m;}const first=Math.max(0,lo-1),last=Math.min(lo,this.keys.length-1),a=this.keys[first],b=this.keys[last],alpha=a===b||a.interpolation==='step'||this.layouts[first]!==this.layouts[last]?0:Math.max(0,Math.min(1,(time-a.time)/(b.time-a.time)));this.bind(first);for(let i=0;i<this.bones.length;i++){const bone=this.bones[i],x=a.value[i],y=alpha?b.value[i]:x;for(let k=0;k<3;k++){bone.position.setComponent(k,x.position[k]+(y.position[k]-x.position[k])*alpha);bone.scale.setComponent(k,x.scale[k]+(y.scale[k]-x.scale[k])*alpha);}bone.quaternion.fromArray(x.quaternion).slerp(this.q.fromArray((alpha?y:x).quaternion),alpha).normalize();}this.group?.updateMatrixWorld(true);}
}

function reduceFixedSkeletalKeys(keys,tolerance){if(!Number.isFinite(tolerance)||tolerance<0)throw Error('키 오차 범위 오류');if(keys.length<3)return keys;const keep=new Set([0,keys.length-1]),pending=[[0,keys.length-1]],aQ=new Quaternion(),bQ=new Quaternion(),actual=new Quaternion();while(pending.length){const [first,last]=pending.pop();if(last-first<2)continue;let best=-1,error=tolerance;const a=keys[first],b=keys[last];for(let i=first+1;i<last;i++){const t=(keys[i].time-a.time)/(b.time-a.time);let distance=0;for(let j=0;j<a.value.length;j++){const x=a.value[j],y=b.value[j],v=keys[i].value[j];if(!v||x.bone!==v.bone||y.bone!==v.bone)throw Error('녹화 중 골격 구성이 바뀌었어요.');for(const field of ['position','scale'])for(let k=0;k<3;k++)distance=Math.max(distance,Math.abs(v[field][k]-(x[field][k]+(y[field][k]-x[field][k])*t)));distance=Math.max(distance,aQ.fromArray(x.quaternion).slerp(bQ.fromArray(y.quaternion),t).angleTo(actual.fromArray(v.quaternion)));}if(distance>error){error=distance;best=i;}}if(best>=0){keep.add(best);pending.push([first,best],[best,last]);}}return [...keep].sort((a,b)=>a-b).map(i=>keys[i]);}

export function reduceSkeletalKeys(keys,tolerance){if(!Number.isFinite(tolerance)||tolerance<0)throw Error('키 오차 범위 오류');const out=[];let start=0;for(let i=1;i<=keys.length;i++)if(i===keys.length||!samePoseLayout(keys[i-1].value,keys[i].value)){out.push(...reduceFixedSkeletalKeys(keys.slice(start,i),tolerance));start=i;}return out;}
